#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
# SPDX-FileCopyrightText: Netresearch DTT GmbH
# Self-test for release-notes-status.sh body classification — no network.
#
# Pins the two shapes that must be recognised as "not finished", because both
# render on GitHub exactly like a finished release and are therefore invisible
# to review: the auto-generated "## Changes" PR-title list, and the CI stub
# body ("see CHANGELOG.md for details").
#
# Also pins the false positive found while building it: the harvest script's
# own header line contains "@mention each INLINE at their change", so extracting
# credits without dropping comment lines invents a contributor called "@mention"
# and reports every finished release as missing them.
set -uo pipefail

fail=0
check() { # check <name> <expected> <actual>
  if [ "$2" = "$3" ]; then
    printf 'ok   - %s\n' "$1"
  else
    printf 'FAIL - %s\n       expected: [%s]\n       actual:   [%s]\n' "$1" "$2" "$3"
    fail=1
  fi
}

# --- the auto-generated shape -------------------------------------------------
# Calls the real classifier. This used to be a retyped copy of the check, so it
# agreed with the check while the check passed GitHub's own generated list.
# The path is computed at runtime, so shellcheck cannot follow it without -x;
# the script guards its own main body and exits early when sourced.
# shellcheck disable=SC1091
. "$(dirname "${BASH_SOURCE[0]}")/../release-notes-status.sh"
is_autogenerated() { autogenerated_body "$1"; }
credited() { credit_mentioned "$1" "$2" && echo 1 || echo 0; }

ci_body='## Changes
- chore: release v0.13.0 (#231)
- feat(secret): shared catalogue (#230)

## Installation'
check "CI PR-title list is autogenerated"      1 "$(is_autogenerated "$ci_body")"

narrative='## Highlights

Two pull requests, one theme. Fixed by @alice in #230.

## Installation'
check "narrative body is not autogenerated"    0 "$(is_autogenerated "$narrative")"

# A narrative that merely *mentions* a PR must not trip the heuristic.
prose='## Highlights

The rotation fix (#284) landed here.

## Installation'
check "prose citing one PR is not autogenerated" 0 "$(is_autogenerated "$prose")"

# GitHub's generated list, copied verbatim from the published body of
# netresearch/git-workflow-skill v1.36.0 (2026-10-23). The check reported it as
# `ok — narrative, credits and CI blocks all present`: it counted only
# `- ... (#123)` lines, and GitHub writes `* ... by @login in <pull URL>`.
github_generated=$(cat <<'BODY'
## What's Changed
* chore(deps): update pre-commit hook netresearch/skill-repo-skill to v2.4.0 by @renovate[bot] in https://github.com/netresearch/git-workflow-skill/pull/389
* chore(deps): update step-security/harden-runner action to v2.22.1 by @renovate[bot] in https://github.com/netresearch/git-workflow-skill/pull/390
* docs(git-workflow): dockerized hooks in worktrees and hanging SSH mux sockets by @aseemann in https://github.com/netresearch/git-workflow-skill/pull/381
* fix(advanced-git): rescue a plain clone's refs into refs/rescue, not heads and tags by @CybotTM in https://github.com/netresearch/git-workflow-skill/pull/391
* feat(pr-status): list jobs that never got a runner as not started by @CybotTM in https://github.com/netresearch/git-workflow-skill/pull/388
* fix(pr-status): name never-reported contexts in the busy wait by @CybotTM in https://github.com/netresearch/git-workflow-skill/pull/392
* chore(deps): update github/codeql-action action to v4.38.3 by @renovate[bot] in https://github.com/netresearch/git-workflow-skill/pull/393
* chore(deps): update pre-commit hook astral-sh/ruff-pre-commit to v0.17.0 by @renovate[bot] in https://github.com/netresearch/git-workflow-skill/pull/394
* chore(deps): update github/codeql-action action to v4.39.0 by @renovate[bot] in https://github.com/netresearch/git-workflow-skill/pull/396
* chore(deps): update pre-commit hook astral-sh/ruff-pre-commit to v0.17.1 by @renovate[bot] in https://github.com/netresearch/git-workflow-skill/pull/397
* chore(renovate): extend the netresearch org preset by @CybotTM in https://github.com/netresearch/git-workflow-skill/pull/398
* docs(pr-workflow): read a flagged hunk's stated reason before changing it by @CybotTM in https://github.com/netresearch/git-workflow-skill/pull/400
* fix(pr-status): read the GraphQL answer from a file, not argv by @CybotTM in https://github.com/netresearch/git-workflow-skill/pull/399
* chore(release): v1.36.0 by @CybotTM in https://github.com/netresearch/git-workflow-skill/pull/402


**Full Changelog**: https://github.com/netresearch/git-workflow-skill/compare/v1.35.1...v1.36.0
BODY
)
check "GitHub's generated list is autogenerated (git-workflow-skill v1.36.0)" \
      1 "$(is_autogenerated "$github_generated")"
check "its by-lines are not credit" 0 "$(credited "$github_generated" @aseemann)"

# A one-PR release generates a single bullet, plus a New Contributors section.
one_pr='## What'"'"'s Changed
* fix: one change by @alice in https://github.com/o/r/pull/7

## New Contributors
* @alice made their first contribution in https://github.com/o/r/pull/7

**Full Changelog**: https://github.com/o/r/compare/v1.0.0...v1.0.1'
check "a one-bullet generated list is autogenerated" 1 "$(is_autogenerated "$one_pr")"
check "a first-contribution line is not credit"      0 "$(credited "$one_pr" @alice)"

# Controls: two rewritten bodies, copied verbatim from their published
# releases (2026-10-23). Both credit with `#N by @login` and must stay ok.
rewritten_gws=$(cat <<'BODY'
## Highlights

`pr-status.sh` now runs where a command line is capped at 32767 characters, as on Windows, and names the structural reasons a pull request is BLOCKED instead of hiding them behind a review action.

## pr-status.sh

- **Runs on Windows.** The large jq programs now ship as `pr-status-evaluate.jq` and `pr-status-investigate.jq` beside the script, and the GitHub payloads reach jq on stdin, so no jq invocation comes near the Windows argv limit. Reported by @nilzen-dev in #395, fixed in #405 by @CybotTM.
- **Structural blockers come first.** On a BLOCKED pull request with unsigned commits and a known signature requirement (classic protection or a `required_signatures` ruleset), the verdict is `fix-signatures` even where a review action would otherwise have been offered. A BLOCKED verdict also names required contexts that never reported and, on a fork pull request, the inferred CodeQL default-setup gap. On a merge history it no longer suggests a linear rebase (#407 by @CybotTM).

## Documentation

- The pull-request workflow reference describes how to re-sign a contributor's signed-off but unsigned commits (#407).
- The merge-gate watcher reference attributes merge-queue checks by their check-suite branch (#404).
- The git reference covers pinning git output that a script parses against the user's config, and counting renames with `--numstat` (#403).
- A GitHub dismissal of a SonarCloud alert is synced back to SonarCloud; the reference now says so (#406).

## Maintenance

- The command validator hook no longer raises CodeQL notes (#409).
- CI reports the required checks for merge-queue entries (#401), and the workflows follow the current `netresearch/.github` skill template, including a weekly security scan (#408, #410).

**Full Changelog**: https://github.com/netresearch/git-workflow-skill/compare/v1.36.0...v1.36.1
BODY
)
check "rewritten git-workflow-skill v1.36.1 is not autogenerated" 0 "$(is_autogenerated "$rewritten_gws")"
check "v1.36.1 credits @CybotTM"    1 "$(credited "$rewritten_gws" @CybotTM)"
check "v1.36.1 credits @nilzen-dev" 1 "$(credited "$rewritten_gws" @nilzen-dev)"

rewritten_brand=$(cat <<'BODY'
## Highlights

The skill now describes how a branded standalone page is built, not only which colours, fonts and logo it uses, and ships a stylesheet and templates that implement it. The contrast audit detects dark schemes reliably and checks focus indicators and form-control boundaries against WCAG SC 1.4.11. The brand rules themselves (colours, Raleway/Open Sans, logo, footer, contrast roles) are unchanged, and hosted TYPO3 manuals keep their own profile.

## Page construction

- `SKILL.md` gains *Building a Standalone Branded Page*: seven rules for building a page from the brand rules. The reasoning and the component library are in `references/web-design.md`, component tokens with light and dark values and measured contrast ratios in `references/colors.md`. Contributed by @jonasgwozdz in #110 (landed on `main` through #130).
- `templates/styles.css` is rewritten on the existing tokens; every previous class name and token is still defined. It adds hairline borders with layered shadows, a solid 3px focus outline that also works on the gradient and in forced-colours mode, no text below 14px, and new components: badges, metric tiles, notices, tables, segmented control, drawn checkbox and radio, select, split layout with steps, app header band, dialog and skip link (#110 by @jonasgwozdz).
- Form help texts on the landing-page and account-form templates are tied to their inputs with `aria-describedby`, the account form's fields are required, and `typography.md` matches the `.lead` size and responsive headings of the stylesheet (#131 by @CybotTM, from review findings on #110).

## Contrast audit

- `contrast-audit.cjs` now reports `darkScheme: true` for every page whose colours switch under `prefers-color-scheme` or `data-theme`, including `file://` pages with external stylesheets, which were previously reported as having no dark scheme. It reads computed colours under each scheme instead of scanning stylesheet rules, and `--scheme dark` measures a `data-theme` dark palette too. Reported in #121 and fixed in #122 by @CybotTM.
- A run now fails on a focus indicator or a form-control boundary below 3:1 (SC 1.4.11). The audit compares each element's focused and unfocused state, measures the parts that changed, and checks results that pass the colour model again on screenshots (#122 by @CybotTM).

## Repository

- CI workflows synced with the `netresearch/.github` skill templates (#132, #133).

**Full Changelog**: https://github.com/netresearch/netresearch-branding-skill/compare/v3.0.0...v3.1.0
BODY
)
check "rewritten netresearch-branding-skill v3.1.0 is not autogenerated" 0 "$(is_autogenerated "$rewritten_brand")"
check "v3.1.0 credits @jonasgwozdz" 1 "$(credited "$rewritten_brand" @jonasgwozdz)"
check "v3.1.0 credits @CybotTM"     1 "$(credited "$rewritten_brand" @CybotTM)"

# --- the CI stub --------------------------------------------------------------
is_stub() { printf '%s' "$1" | grep -qiE 'see CHANGELOG\.md for details' && echo 1 || echo 0; }
check "CI stub body detected"                  1 "$(is_stub 'Release v1.2.3 — see CHANGELOG.md for details')"
check "narrative is not a stub"                0 "$(is_stub "$narrative")"

# --- credit extraction --------------------------------------------------------
# Mirrors the pipeline in release-notes-status.sh: drop the harvest header
# before extracting @mentions.
extract_people() { printf '%s' "$1" | grep -v '^#' | grep -oE '@[A-Za-z0-9-]+' | sort -u | tr '\n' ' '; }

harvest_output='# Contributors in v1..v2 — @mention each INLINE at their change (do not paste as a section):
code authors: @alice @bob'
check "harvest header does not become a person" "@alice @bob " "$(extract_people "$harvest_output")"

# --- hand-written Contributors section ----------------------------------------
has_section() { printf '%s' "$1" | grep -qiE '^#+ *Contributors' && echo 1 || echo 0; }
check "hand-written Contributors section flagged" 1 "$(has_section '## Contributors
- @alice')"
check "inline credit is not a section"            0 "$(has_section "$narrative")"

# --- which release the range starts from --------------------------------------
# This one calls the real function rather than mirroring it, because the defect
# it pins was in the selection itself and a mirror would have agreed with the
# bug. GitHub lists releases newest-first across every branch, so on a
# repository maintaining two majors the neighbour of a v12 patch is a v13
# release — and harvesting that range reports everyone who worked on v13 as an
# uncredited contributor to the v12 patch. Observed on
# a measured TYPO3 extension: v12.0.12 was compared against v13.9.0 and
# demanded credit for two people who had not touched it.

interleaved='v13.10.2
v13.10.1
v12.0.14
v13.10.0
v13.9.1
v12.0.13
v12.0.12
v13.9.0
v13.8.3
v12.0.11'

check "v12 patch follows the v12 line"   v12.0.11 "$(previous_release_on_line v12.0.12 "$interleaved")"
check "v12 minor skips the v13 releases" v12.0.13 "$(previous_release_on_line v12.0.14 "$interleaved")"
check "v13 patch follows the v13 line"   v13.10.1 "$(previous_release_on_line v13.10.2 "$interleaved")"
check "v13 minor skips the v12 releases" v13.9.1  "$(previous_release_on_line v13.10.0 "$interleaved")"
check "oldest on its line has no predecessor" "" "$(previous_release_on_line v12.0.11 "$interleaved")"
check "single-line repo is unaffected"   v1.2.0 "$(previous_release_on_line v1.2.1 'v1.2.1
v1.2.0
v1.1.0')"

# --- what counts as crediting a contributor -----------------------------------
# Calls the real predicate. In a release body only a bare `@login` is a
# mention: `[@login](https://github.com/login)` renders as a plain link,
# which notifies nobody (references/release-process.md). A substring test
# counted that link as credit, and it also counted `@alicebob` and
# `mail@alice.dev` as credit for `@alice`.
check "profile link is not a mention"          0 "$(credited 'Fixed by [@alice](https://github.com/alice) in #230.' @alice)"
check "a mention inside a link label is not"   0 "$(credited 'Fixed [by @alice](https://github.com/alice).' @alice)"
check "a reference-style link is not a mention" 0 "$(credited '[@alice][1] fixed it.

[1]: https://github.com/alice' @alice)"
check "bare mention after a PR link counts"    1 "$(credited '([#43](https://github.com/o/r/pull/43) by @alice)' @alice)"
check "bare mention at line start counts"      1 "$(credited '@alice fixed the rotation.' @alice)"
check "bare mention mid-sentence counts"       1 "$(credited 'Fixed by @alice in #230.' @alice)"
check "bare mention before punctuation counts" 1 "$(credited 'Thanks (@alice), @bob.' @alice)"
check "bare mention at end of body counts"     1 "$(credited 'Thanks @bob' @bob)"
check "bare mention beside a link counts"      1 "$(credited '[@alice](https://github.com/alice)
Also fixed by @alice.' @alice)"
check "a longer login is not the shorter one"  0 "$(credited 'Fixed by @alicebob.' @alice)"
check "a hyphenated login is not its prefix"   0 "$(credited 'Fixed by @alice-b.' @alice)"
check "an e-mail address is not a mention"     0 "$(credited 'Reported to mail@alice.dev.' @alice)"

# Structural: the credit loop must go through that predicate, or the tests above
# pin a function the check never calls.
callers=$(grep -v '^[[:space:]]*#' "$(dirname "${BASH_SOURCE[0]}")/../release-notes-status.sh" \
          | grep -cF "credit_mentioned \"\$body\" \"\$p\"" || true)
check "the credit loop calls credit_mentioned" 1 "$callers"

# Structural: the overhaul verdict must come from the classifier the cases above
# call, or they pin a function the check never reaches.
classifier_calls=$(grep -v '^[[:space:]]*#' "$(dirname "${BASH_SOURCE[0]}")/../release-notes-status.sh" \
                   | grep -cF "raw=\$(autogenerated_body \"\$body\")" || true)
check "the overhaul check calls autogenerated_body" 1 "$classifier_calls"

# --- a match must survive the size of the text --------------------------------
# `printf '%s' "$big" | grep -q PAT` under `set -o pipefail` reports a FOUND
# match as a failed command whenever grep exits before printf has finished
# writing: printf takes SIGPIPE, and 141 is what pipefail propagates. It fails
# silently and in the direction that hides defects — the release whose CI
# blocks were gone read "ok — CI blocks all present", because the check found
# a block in the comparison set and the find is what broke it.
#
# Whether the writer actually dies depends on how much of the text fits in the
# 64 KB pipe buffer before grep quits, so the failure is size-dependent and the
# real case sits in the fuzzy part of that curve. Measured here, match at the
# top: 50 KB fails 2 of 20 runs, 70 KB fails 8, 100 KB fails 20 of 20. The live
# blob was 52,989 bytes with the match at byte 2,474 and flipped the verdict
# roughly one run in eight.
#
# So the probe uses 100 KB, where the pre-fix pipeline fails every single time
# and the test cannot pass by luck. It pins the construct, not the size — the
# assertion further down keeps every call site off that construct regardless of
# how large the texts happen to be.
haystack="intro line
## Software Bill of Materials
$(head -c 100000 /dev/zero | tr '\0' 'x')"

hits=0
for _ in $(seq 1 20); do
  body_has "$haystack" -F '## Software Bill of Materials' && hits=$((hits + 1))
done
check "early match in a 100 KB text is found every time" 20 "$hits"

misses=0
for _ in $(seq 1 20); do
  body_has "$haystack" -F '## Verify your download' || misses=$((misses + 1))
done
check "absent pattern reports absent every time"        20 "$misses"

# Size-independent: no call site may reintroduce the pipeline. The behavioural
# probe above only fires above the pipe buffer, and the texts this script hands
# around are smaller than that — a reintroduced `| grep -q` on a 30 KB body
# would slip past it while still flipping verdicts in the field.
pipelines=$(grep -v '^[[:space:]]*#' "$(dirname "${BASH_SOURCE[0]}")/../release-notes-status.sh" \
            | grep -c '| *grep -q' || true)
check "no pattern test goes through a pipe"            0 "$pipelines"

# --- which CI blocks the overhaul check looks for -----------------------------
# The list is read from the script, not retyped here: a copy would agree with
# whatever the check does and stay green when a section is dropped from it.
# `## Container image` is the section this pins. `release-go-app.yml` emits it
# for every run that builds a container, and it was absent from the check's list
# until a measured ldap-manager v1.7.0 overhaul destroyed it while this script
# answered `ok`. The sibling comparison cannot recover from that on its own:
# once a block is gone from every release on the line, no sibling carries it and
# the check has nothing left to compare against.
check "Container image is a CI block the check looks for" \
      1 "$(ci_block_sections | grep -cxF 'Container image')"
check "every orchestrator section is listed" \
      4 "$(ci_block_sections | grep -c .)"

# Structural: the check must READ that list rather than carry its own copy.
literal=$(grep -c 'for s in Installation' \
          "$(dirname "${BASH_SOURCE[0]}")/../release-notes-status.sh" || true)
check "the loop reads ci_block_sections, not a retyped list" 0 "$literal"

exit $fail
